// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
// Compound component: Menu (trigger + popover wrapper) + MenuItem + MenuSeparator + MenuSection (+ Header) + MenuSubmenuTrigger.
import {
  Collection,
  Header as AriaHeader,
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  MenuSection as AriaMenuSection,
  MenuTrigger,
  Separator,
  SubmenuTrigger as AriaSubmenuTrigger,
} from "react-aria-components";
import { PopoverContent } from "./Popover";
import type {
  HeaderProps as AriaHeaderProps,
  MenuItemProps as AriaMenuItemProps,
  MenuProps as AriaMenuProps,
  MenuSectionProps as AriaMenuSectionProps,
  MenuTriggerProps as AriaMenuTriggerProps,
  SeparatorProps,
  SubmenuTriggerProps as AriaSubmenuTriggerProps,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import "./Menu.css";

export interface MenuProps
  extends Omit<AriaMenuProps<object>, "className" | "children">,
    Omit<AriaMenuTriggerProps, "children" | "trigger"> {
  /** Trigger that opens the menu. When omitted, renders only the item list with no trigger +
   * Popover (for a submenu where MenuSubmenuTrigger already provides the trigger + Popover). */
  trigger?: ReactNode;
  /** Trigger interaction mode — `press` (default) or `longPress` (touch context menu). Forwarded
   *  to RAC `MenuTrigger`'s `trigger` (our `trigger` prop is the trigger *element*, so the names
   *  are separated). */
  triggerType?: "press" | "longPress";
  /** MenuItem list. */
  children?: ReactNode;
  /** Additional class (optional). sd-menu is always preserved. */
  className?: string;
  /** Forwarded to the underlying menu DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function Menu({
  trigger,
  triggerType,
  children,
  className,
  ref,
  isOpen,
  defaultOpen,
  onOpenChange,
  ...props
}: MenuProps) {
  const list = (
    <AriaMenu
      {...props}
      ref={ref}
      className={className ? `sd-menu ${className}` : "sd-menu"}
    >
      {children}
    </AriaMenu>
  );

  if (!trigger) {
    return list;
  }

  return (
    <MenuTrigger
      trigger={triggerType}
      isOpen={isOpen}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {trigger}
      {/* The shared PopoverContent owns the overlay surface (surface small + elevation high).
          Menu manages role=menu · roving-tabindex itself, so omit Dialog wrapping (noDialog). */}
      <PopoverContent noDialog size="small">
        {list}
      </PopoverContent>
    </MenuTrigger>
  );
}

export interface MenuItemProps extends Omit<AriaMenuItemProps, "className"> {
  /** Optional leading icon. Pass `textValue` when the label is not plain text. */
  icon?: ReactNode;
  /** Trailing content pinned to the item's end: a shortcut (`Keyboard`), or a short note on why the
   *  command is unavailable. It is read as part of the item's name; type-to-select matches
   *  `textValue` alone, which string `children` still provide. */
  trailing?: ReactNode;
  /** Additional class (optional). sd-menu__item is always preserved. */
  className?: string;
  /** Forwarded to the underlying <div> DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function MenuItem({ icon, trailing, className, children, textValue, ...props }: MenuItemProps) {
  return (
    <AriaMenuItem
      {...props}
      // RAC derives an item's textValue from *string* children, but this component always
      // renders a function child (icon + label), so RAC would see textValue="" and both
      // type-to-select and Autocomplete filtering would break. Re-derive it from string
      // children the same way GridListItem does (GridList.tsx). Explicit textValue wins.
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      className={
        className
          ? `sd-menu__item sd-type-label-medium ${className}`
          : "sd-menu__item sd-type-label-medium"
      }
    >
      {(renderProps) => (
        <>
          {icon && (
            <span className="sd-menu__item-icon" aria-hidden="true">
              {icon}
            </span>
          )}
          {typeof children === "function" ? children(renderProps) : children}
          {trailing != null && <span className="sd-menu__item-trailing">{trailing}</span>}
        </>
      )}
    </AriaMenuItem>
  );
}

export interface MenuSeparatorProps extends Omit<SeparatorProps, "className"> {
  /** Additional class (optional). sd-menu__separator is always preserved. */
  className?: string;
}

export function MenuSeparator({ className, ...props }: MenuSeparatorProps) {
  return (
    <Separator
      {...props}
      className={className ? `sd-menu__separator ${className}` : "sd-menu__separator"}
    />
  );
}

export interface MenuSectionProps<T extends object = object>
  extends Omit<AriaMenuSectionProps<T>, "className" | "children"> {
  /** Optional section-header text — when passed, renders the header automatically (the same convenience as ListBoxSection). */
  title?: string;
  /** MenuItem list or dynamic collection renderer. */
  children?: AriaMenuSectionProps<T>["children"];
  /** Additional class (optional). sd-menu__section is always preserved. */
  className?: string;
}

export function MenuSection<T extends object = object>({
  title,
  className,
  children,
  ...props
}: MenuSectionProps<T>) {
  return (
    <AriaMenuSection
      {...props}
      className={className ? `sd-menu__section ${className}` : "sd-menu__section"}
    >
      {/* One rung below the `label-medium` items it heads — `naming-convention.md` § The size
          axis defaults to `medium`, CONTRASTIVE. */}
      {title && (
        <AriaHeader className="sd-menu__section-header sd-type-label-small">
          {title}
        </AriaHeader>
      )}
      {typeof children === "function" ? <Collection>{children}</Collection> : children}
    </AriaMenuSection>
  );
}

export interface MenuSectionHeaderProps extends Omit<AriaHeaderProps, "className"> {
  /** Additional class (optional). sd-menu__section-header is always preserved. */
  className?: string;
}

export function MenuSectionHeader({ className, ...props }: MenuSectionHeaderProps) {
  return (
    <AriaHeader
      {...props}
      className={
        className
          // One rung below the items it heads — CONTRASTIVE, per naming-convention.md.
          ? `sd-menu__section-header sd-type-label-small ${className}`
          : "sd-menu__section-header sd-type-label-small"
      }
    />
  );
}

// Submenu trigger — a context-only wrapper that lets RAC wrap exactly two children
// [trigger item, Popover] without DOM of its own (the same kind as Autocomplete/FileTrigger).
// This component itself has no style because its children (MenuItem/Popover/Menu) own the look.
export interface MenuSubmenuTriggerProps extends AriaSubmenuTriggerProps {}

export function MenuSubmenuTrigger({ children, ...props }: MenuSubmenuTriggerProps) {
  const [item, submenu] = children;
  return (
    <AriaSubmenuTrigger {...props}>
      {item}
      {/* RAC renders the second child under PopoverContext, so that position **must be a Popover**
          (Menu.mjs SubmenuTrigger). Our Menu renders only the list when used without trigger, so
          passing it directly expands the submenu inline inside the parent menu (role=menu inside
          role=menu). Therefore the overlay surface is wrapped here — the same surface small +
          noDialog as top-level Menu. */}
      <PopoverContent noDialog size="small">
        {submenu}
      </PopoverContent>
    </AriaSubmenuTrigger>
  );
}

/* Menu.css — .sd-menu (+ BEM 서브파트)
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조.
   오버레이 면(배경·보더·radius·shadow·padding·모션)은 공용 PopoverContent 가 소유한다
   (Menu.tsx: <PopoverContent noDialog size="small">). */
.sd-menu {
  outline: none;
  display: flex;
  flex-direction: column;
  gap: var(--sd-menu-gap);
}

.sd-menu__item {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: var(--sd-menu-item-gap);
  min-height: var(--sd-menu-item-min-height);
  padding: var(--sd-menu-item-padding-block) var(--sd-menu-item-padding-inline);
  border-radius: var(--sd-menu-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-menu-item-foreground);
  /* A MenuItem with `href` renders an <a>, which the user agent underlines; a menu row reads as a
     command or destination by its place in the menu, not by an underline. */
  text-decoration: none;
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-menu-item-state-hover-current: var(--sd-state-hover);
  --sd-menu-item-state-pressed-current: var(--sd-state-pressed);
}

/* Interaction state-layer: hover/pressed tint composites over the rest/selected
   fill via a pointer-events-none ::after overlay (ADR-0009 state-layer). */
.sd-menu__item::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-menu__item[data-hovered]::after,
.sd-menu__item[data-focused]::after {
  background: var(--sd-menu-item-state-hover-current);
}
.sd-menu__item[data-pressed]::after {
  background: var(--sd-menu-item-state-pressed-current);
}

.sd-menu__item[data-selected] {
  background: var(--sd-menu-item-background-selected);
  --sd-menu-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-menu-item-state-pressed-current: var(--sd-state-pressed-selected);
}

.sd-menu__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* Only the menu-specific inset; the line itself (height + background) comes from
   the wrapped generic .sd-separator. */
.sd-menu__separator {
  margin: var(--sd-menu-separator-margin-block) var(--sd-menu-separator-margin-inline);
}

/* `section-gap` parts one SECTION from the next and nothing else. Spent as the section's own
   flex `gap` it landed between EVERY child, which pushed the header away from the group it
   labels and toward the group above it — measured in every brand, the header sat closer to the
   previous section's last row than to the first row it names. It also re-spaced the rows
   themselves, so a list's row rhythm changed the moment it gained a header. Rows inside a
   section are now parted by whatever parts rows in a section-less list, which is the root gap. */
.sd-menu__section {
  display: flex;
  flex-direction: column;
  gap: var(--sd-menu-gap);
}

/* ADJACENCY is an assumption, not a guarantee. React Aria's `Virtualizer` wraps each node in a
   `VirtualizerItem`, which would split this pair and silently drop the separation. Nothing under
   `src/**` uses it and no component exposes it, so nothing rendered is wrong; a cold review found
   no selector correct under both shapes at no cost, because spacing an absolutely positioned
   wrapper fights the virtualizer's own layout. Re-measure here first if virtualization is ever
   offered. */
.sd-menu__section + .sd-menu__section {
  margin-block-start: var(--sd-menu-section-gap);
}

.sd-menu__section-header {
  padding-block: var(--sd-menu-section-header-padding-block-start) var(--sd-menu-section-header-padding-block-end);
  padding-inline: var(--sd-menu-section-header-padding-inline);
  color: var(--sd-menu-section-header-foreground);
}

/* The item's end: a shortcut, or a note on why the command is unavailable, pinned by one auto margin. */
.sd-menu__item-trailing {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: var(--sd-menu-item-gap);
  margin-inline-start: auto;
}

.sd-menu__item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-menu-item-icon-size);
  width: var(--sd-menu-item-icon-size);
  height: var(--sd-menu-item-icon-size);
  font-size: var(--sd-menu-item-icon-size);
}
